import { useState, useCallback, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  ArrowLeft, HelpCircle, Trophy, Lock, RotateCcw,
} from "lucide-react";
import { SeedType, SEED_CONFIGS } from "@/types/game";
import { audioManager } from "@/utils/audioManager";
import { useWordStore } from "@/store/useWordStore";
import QuizModal from "@/components/QuizModal";
import SlotMachineReward from "@/components/SlotMachineReward";

// ====== 玩法常量 ======
// 10 列主槽位，每槽容量 10 格；凑齐 9 个同类型方块即归类完成（不消除，保留占位）。
// 9 种类型 × 9 个 = 81 个方块，将 9 个槽位全部归类完成即胜利，触发水果机抽奖。
const COL_COUNT = 10;
const CAPACITY = 10;
const CLEAR_COUNT = 9;
const BLOCK_TYPES: SeedType[] = [
  "carrot", "cucumber", "cabbage", "strawberry",
  "tomato", "corn", "sunflower", "watermelon", "kiwi",
];

const TEMP_COUNT = 10;
const TEMP_SLOT_H = 34;
const STORAGE_KEY_TEMP_UNLOCKED = "seed_warehouse_temp_unlocked";

// 视觉尺寸
const BLOCK_PX = 28;
const GAP_PX = 2;
const STEP_PX = BLOCK_PX + GAP_PX;
const SLOT_H = 300;
const SLOT_W = 30;

interface Cell {
  type: SeedType;
  faceUp: boolean;
}

interface SlotRef {
  type: "main" | "temp";
  index: number;
}

interface FlyingState {
  cells: Cell[];
  from: SlotRef;
  to: SlotRef;
  startX: number;
  startY: number;
  endX: number;
  exitY: number;
  dropTargets: number[];
}

function shuffle<T>(arr: T[]): T[] {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function generateBoard(): Cell[][] {
  for (let attempt = 0; attempt < 50; attempt++) {
    const blocks: Cell[] = [];
    for (const t of BLOCK_TYPES) {
      for (let i = 0; i < CLEAR_COUNT; i++) blocks.push({ type: t, faceUp: false });
    }
    shuffle(blocks);
    const emptyIdx = Math.floor(Math.random() * COL_COUNT);
    const cols: Cell[][] = Array.from({ length: COL_COUNT }, () => []);
    let bi = 0;
    for (let c = 0; c < COL_COUNT; c++) {
      if (c === emptyIdx) continue;
      for (let i = 0; i < CLEAR_COUNT; i++) cols[c].push(blocks[bi++]);
      cols[c][cols[c].length - 1].faceUp = true;
    }
    if (cols.every((c) => !isComplete(c))) return cols;
  }
  return [];
}

function cloneCols(cols: Cell[][]): Cell[][] {
  return cols.map((col) => col.map((c) => ({ ...c })));
}

function getTopGroup(col: Cell[]): Cell[] {
  if (col.length === 0) return [];
  const top = col[col.length - 1];
  if (!top.faceUp) return [];
  const group: Cell[] = [];
  for (let i = col.length - 1; i >= 0; i--) {
    if (col[i].faceUp && col[i].type === top.type) group.push(col[i]);
    else break;
  }
  return group.reverse();
}

function isComplete(col: Cell[]): boolean {
  return col.length === CLEAR_COUNT && col.every((c) => c.type === col[0].type);
}

function blockTopInSlot(k: number): number {
  return SLOT_H - k * STEP_PX + GAP_PX;
}

function getMoveGroup(
  cols: Cell[][],
  tempSlots: (Cell | null)[],
  source: SlotRef,
): Cell[] {
  if (source.type === "main") {
    return getTopGroup(cols[source.index]);
  }
  const cell = tempSlots[source.index];
  return cell ? [cell] : [];
}

// 计算从源到目标的移动可行性，返回 { valid, moveCount, reason }
function evaluateMove(
  cols: Cell[][],
  tempSlots: (Cell | null)[],
  tempUnlocked: number,
  from: SlotRef,
  to: SlotRef,
): { valid: boolean; moveCount: number; reason?: string } {
  if (from.type === to.type && from.index === to.index)
    return { valid: false, moveCount: 0 };

  const group = getMoveGroup(cols, tempSlots, from);
  if (group.length === 0)
    return { valid: false, moveCount: 0, reason: "没有可移动的方块" };

  if (to.type === "temp") {
    if (to.index >= tempUnlocked)
      return { valid: false, moveCount: 0, reason: "该临时槽位未解锁" };
    if (tempSlots[to.index] !== null)
      return { valid: false, moveCount: 0, reason: "临时槽位已有方块" };
    if (group.length !== 1)
      return { valid: false, moveCount: 0, reason: "只能移动单个方块到临时槽位" };
    return { valid: true, moveCount: 1 };
  }

  // 目标是主槽位
  const dst = cols[to.index];
  const moveCount = group.length;
  if (dst.length > 0 && dst[dst.length - 1].type !== group[0].type)
    return { valid: false, moveCount: 0, reason: "只有同类型才能叠放" };
  if (dst.length + moveCount > CAPACITY)
    return { valid: false, moveCount: 0, reason: "目标槽位放不下" };
  return { valid: true, moveCount };
}

function hasAnyMove(
  cols: Cell[][],
  tempSlots: (Cell | null)[],
  tempUnlocked: number,
): boolean {
  // 主→主
  for (let f = 0; f < COL_COUNT; f++) {
    for (let t = 0; t < COL_COUNT; t++) {
      if (evaluateMove(cols, tempSlots, tempUnlocked,
        { type: "main", index: f }, { type: "main", index: t }).valid)
        return true;
    }
  }
  // 主→临时
  for (let f = 0; f < COL_COUNT; f++) {
    for (let t = 0; t < TEMP_COUNT; t++) {
      if (evaluateMove(cols, tempSlots, tempUnlocked,
        { type: "main", index: f }, { type: "temp", index: t }).valid)
        return true;
    }
  }
  // 临时→主
  for (let f = 0; f < TEMP_COUNT; f++) {
    for (let t = 0; t < COL_COUNT; t++) {
      if (evaluateMove(cols, tempSlots, tempUnlocked,
        { type: "temp", index: f }, { type: "main", index: t }).valid)
        return true;
    }
  }
  return false;
}

function checkWin(cols: Cell[][], tempSlots: (Cell | null)[]): boolean {
  // 胜利：9 个槽凑齐 9 个同类型（纯色），1 个空槽，临时槽位全空
  const completedCount = cols.filter((c) => isComplete(c)).length;
  return completedCount === COL_COUNT - 1 && tempSlots.every((s) => s === null);
}

// ====== 单个方块 ======
function Block({ cell }: { cell: Cell }) {
  const cfg = SEED_CONFIGS[cell.type];
  if (cell.faceUp) {
    return (
      <div
        className="rounded-md flex items-center justify-center shadow-sm border border-black/25 transition-all duration-150 shrink-0"
        style={{
          width: BLOCK_PX, height: BLOCK_PX,
          background: `linear-gradient(135deg, ${cfg.color}, ${cfg.color}cc)`,
          fontSize: 15,
        }}
      >
        <span>{cfg.fruitEmoji}</span>
      </div>
    );
  }
  return (
    <div
      className="rounded-md flex items-center justify-center bg-gradient-to-br from-slate-700 to-slate-800 border border-slate-600/50 shadow-sm transition-all duration-150 shrink-0"
      style={{ width: BLOCK_PX, height: BLOCK_PX }}
    >
      <span className="text-slate-500 text-[11px] font-bold">?</span>
    </div>
  );
}

export default function SeedWarehouseGame() {
  const navigate = useNavigate();
  const [cols, setCols] = useState<Cell[][]>(() => generateBoard());
  const [tempSlots, setTempSlots] = useState<(Cell | null)[]>(() => Array(TEMP_COUNT).fill(null));
  const [tempUnlockedCount, setTempUnlockedCount] = useState<number>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_TEMP_UNLOCKED);
      return saved ? Math.max(1, Math.min(TEMP_COUNT, parseInt(saved))) : 1;
    } catch { return 1; }
  });
  const [selected, setSelected] = useState<SlotRef | null>(null);
  const [won, setWon] = useState(false);
  const [noMoves, setNoMoves] = useState(false);
  const [showRules, setShowRules] = useState(false);
  const [hint, setHint] = useState("");
  const [flying, setFlying] = useState<FlyingState | null>(null);

  const [showQuiz, setShowQuiz] = useState(false);
  const [showReward, setShowReward] = useState(false);
  const [pendingUnlockSlot, setPendingUnlockSlot] = useState<number | null>(null);

  const hintTimer = useRef<number | null>(null);
  const columnRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const tempSlotRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const gameAreaRef = useRef<HTMLDivElement | null>(null);
  const flyingInnerRef = useRef<HTMLDivElement | null>(null);

  const quizSession = useWordStore((s) => s.quizSession);
  const canStartQuiz = useWordStore((s) => s.canStartQuiz);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_TEMP_UNLOCKED, String(tempUnlockedCount));
  }, [tempUnlockedCount]);

  useEffect(() => () => { if (hintTimer.current) clearTimeout(hintTimer.current); }, []);

  // 飞行动画
  useEffect(() => {
    if (!flying) return;
    const container = flyingInnerRef.current;
    if (!container) return;
    const anim = container.animate(
      [
        { transform: `translate3d(${flying.startX}px, ${flying.startY}px, 0)` },
        { transform: `translate3d(${flying.startX}px, ${flying.exitY}px, 0)`, offset: 0.5 },
        { transform: `translate3d(${flying.endX}px, ${flying.exitY}px, 0)` },
      ],
      { duration: 300, easing: "cubic-bezier(0.45, 0.05, 0.3, 1)", fill: "forwards" }
    );
    const blocks = container.querySelectorAll<HTMLElement>(".flying-block");
    const blockAnims: Animation[] = [];
    blocks.forEach((b, i) => {
      const fromY = i * STEP_PX;
      const toY = flying.dropTargets[i] - flying.exitY;
      blockAnims.push(
        b.animate(
          [
            { transform: `translate3d(0, ${fromY}px, 0)` },
            { transform: `translate3d(0, ${toY}px, 0)` },
          ],
          { duration: 200, delay: 300 + i * 55, easing: "cubic-bezier(0.3, 0.7, 0.4, 1)", fill: "forwards" }
        )
      );
    });
    return () => {
      anim.cancel();
      blockAnims.forEach((a) => a.cancel());
    };
  }, [flying]);

  const showHint = (msg: string) => {
    setHint(msg);
    if (hintTimer.current) clearTimeout(hintTimer.current);
    hintTimer.current = window.setTimeout(() => setHint(""), 1600);
  };

  const newGame = useCallback(() => {
    setCols(generateBoard());
    setTempSlots(Array(TEMP_COUNT).fill(null));
    setTempUnlockedCount(1);
    setSelected(null);
    setWon(false);
    setNoMoves(false);
    setHint("");
    setFlying(null);
  }, []);

  const isAnimating = flying !== null;

  // 选中信息
  const selectedGroup = selected ? getMoveGroup(cols, tempSlots, selected) : [];
  const targets: boolean[] = [];
  if (selected) {
    for (let i = 0; i < COL_COUNT; i++)
      targets.push(evaluateMove(cols, tempSlots, tempUnlockedCount, selected, { type: "main", index: i }).valid);
    for (let i = 0; i < TEMP_COUNT; i++)
      targets.push(evaluateMove(cols, tempSlots, tempUnlockedCount, selected, { type: "temp", index: i }).valid);
  }

  // 动画结束后的数据提交
  const finishMove = (from: SlotRef, to: SlotRef, group: Cell[], moveCount: number) => {
    const nextCols = cloneCols(cols);
    const nextTemp = tempSlots.map((s) => (s ? { ...s } : null));
    const n = moveCount;

    // 从源移除
    if (from.type === "main") {
      const src = nextCols[from.index];
      src.splice(src.length - n, n);
      if (src.length > 0 && !src[src.length - 1].faceUp) src[src.length - 1].faceUp = true;
    } else {
      nextTemp[from.index] = null;
    }

    // 放入目标
    if (to.type === "main") {
      const dst = nextCols[to.index];
      for (const cell of group.slice(-n)) dst.push({ ...cell, faceUp: true });
    } else {
      // 临时槽位：只放 1 个
      nextTemp[to.index] = { ...group[group.length - n], faceUp: true };
    }

    setCols(nextCols);
    setTempSlots(nextTemp);
    setFlying(null);
    audioManager.playMoveSfx();

    if (checkWin(nextCols, nextTemp)) {
      setWon(true); audioManager.playWinSfx(); setShowReward(true);
      setNoMoves(false);
    } else {
      // 方块移动后重新判断卡关状态：有解则清除提示，无解则持续显示
      setNoMoves(!hasAnyMove(nextCols, nextTemp, tempUnlockedCount));
    }
  };

  // 获取某个槽位的 DOM 引用
  const getSlotEl = (ref: SlotRef): HTMLButtonElement | null => {
    if (ref.type === "main") return columnRefs.current[ref.index];
    return tempSlotRefs.current[ref.index];
  };

  // 计算方块动画目标位置列表
  const computeDropTargets = (
    to: SlotRef,
    moveCount: number,
  ): number[] => {
    const dstEl = getSlotEl(to);
    const area = gameAreaRef.current;
    if (!dstEl || !area) return [];
    const dstR = dstEl.getBoundingClientRect();
    const areaR = area.getBoundingClientRect();
    const dstTop = dstR.top - areaR.top;

    if (to.type === "main") {
      const dstLen = cols[to.index].length;
      // 如果是源主列，要扣除正在飞走的方块
      const actualDstLen = flying && flying.from.type === "main" && flying.to.type === "main" && flying.to.index === to.index
        ? dstLen - flying.cells.length : dstLen;
      const targets: number[] = [];
      for (let i = 0; i < moveCount; i++)
        targets.push(dstTop + blockTopInSlot(actualDstLen + moveCount - i));
      return targets;
    }
    // 临时槽位：方块居中
    const centerY = dstTop + (TEMP_SLOT_H - BLOCK_PX) / 2;
    return [centerY];
  };

  const handleSlotClick = (ref: SlotRef) => {
    if (won || isAnimating) return;

    // 锁定的临时槽位 → 触发解锁
    if (ref.type === "temp" && ref.index >= tempUnlockedCount) {
      if (canStartQuiz("warehouse")) {
        setPendingUnlockSlot(ref.index);
        setShowQuiz(true);
      } else {
        showHint("需要至少 10 个单词才能解锁");
      }
      return;
    }

    if (selected === null) {
      const group = getMoveGroup(cols, tempSlots, ref);
      if (group.length === 0) {
        if (ref.type === "main") showHint("这是空槽位");
        else showHint("临时槽位为空");
        return;
      }
      if (ref.type === "main" && !cols[ref.index][cols[ref.index].length - 1].faceUp) {
        showHint("顶部方块未翻面");
        return;
      }
      setSelected(ref);
      return;
    }

    if (selected.type === ref.type && selected.index === ref.index) {
      setSelected(null);
      return;
    }

    const evalResult = evaluateMove(cols, tempSlots, tempUnlockedCount, selected, ref);
    if (!evalResult.valid) {
      showHint(evalResult.reason || "无法移动到这里");
      return;
    }

    const from = selected;
    const to = ref;
    const group = getMoveGroup(cols, tempSlots, from);
    const moveCount = evalResult.moveCount;

    setSelected(null);

    const srcEl = getSlotEl(from);
    const dstEl = getSlotEl(to);
    const area = gameAreaRef.current;
    if (!srcEl || !dstEl || !area) {
      finishMove(from, to, group, moveCount);
      return;
    }

    const srcR = srcEl.getBoundingClientRect();
    const dstR = dstEl.getBoundingClientRect();
    const areaR = area.getBoundingClientRect();

    const startX = srcR.left - areaR.left + (srcR.width - BLOCK_PX) / 2;
    const startY = srcR.top - areaR.top + (from.type === "main"
      ? blockTopInSlot(cols[from.index].length)
      : (TEMP_SLOT_H - BLOCK_PX) / 2);

    const endX = dstR.left - areaR.left + (dstR.width - BLOCK_PX) / 2;

    // 出洞/入洞高度：取源和目标中更高者再上移
    const srcTop = srcR.top - areaR.top;
    const dstTop = dstR.top - areaR.top;
    const exitY = Math.min(srcTop, dstTop) - 24;

    const dropTargets = computeDropTargets(to, moveCount);

    setFlying({
      cells: group.slice(-moveCount),
      from, to, startX, startY, endX, exitY, dropTargets,
    });

    const totalMs = 300 + Math.max(0, (moveCount - 1)) * 55 + 200 + 40;
    window.setTimeout(() => finishMove(from, to, group, moveCount), totalMs);
  };

  // Quiz 结果处理
  const handleQuizClose = () => {
    const wonQuiz = quizSession?.isFinished && quizSession?.isWon;
    setShowQuiz(false);
    if (wonQuiz && pendingUnlockSlot !== null) {
      setTempUnlockedCount((c) => Math.min(TEMP_COUNT, Math.max(c, pendingUnlockSlot + 1)));
      showHint(`✨ 临时槽位 ${pendingUnlockSlot + 1} 已解锁！`);
      audioManager.playClearSfx();
    }
    setPendingUnlockSlot(null);
  };

  const selectedIsTemp = selected?.type === "temp";
  const selectedIsMain = selected?.type === "main";

  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 flex flex-col">
      <div className="max-w-md mx-auto w-full flex-1 flex flex-col min-h-0 px-4 py-4">
        {/* 顶栏 */}
        <div className="flex items-center justify-between mb-2 shrink-0">
          <button
            onClick={() => navigate("/farm")}
            className="p-2 rounded-full hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
          >
            <ArrowLeft size={22} />
          </button>
          <div className="flex items-center gap-2">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center shadow-lg shadow-emerald-500/40">
              <span className="text-lg">🌱</span>
            </div>
            <h1 className="text-lg font-bold text-transparent bg-clip-text bg-gradient-to-r from-emerald-300 to-teal-300">
              种子仓库
            </h1>
          </div>
          <div className="flex items-center gap-1">
            {import.meta.env.DEV && (
              <button
                onClick={() => setShowReward(true)}
                className="p-2 rounded-full hover:bg-amber-700/40 text-amber-400/70 hover:text-amber-300 transition-all"
                title="测试抽奖页 (dev)"
              >
                <Trophy size={20} />
              </button>
            )}
            <button
              onClick={newGame}
              className="p-2 rounded-full hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
              title="重新开始"
            >
              <RotateCcw size={20} />
            </button>
            <button
              onClick={() => setShowRules(true)}
              className="p-2 rounded-full hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
            >
              <HelpCircle size={22} />
            </button>
          </div>
        </div>

        {/* 提示栏 */}
        <div className="flex items-center justify-center mb-2 shrink-0 min-h-[1rem]">
          {noMoves ? (
            <span className="text-amber-400 text-xs flex items-center gap-1.5">
              卡关了，解锁临时槽位或者点击右上角 <RotateCcw size={12} /> 按钮重新开始
            </span>
          ) : (
            <span className="text-slate-400 text-xs">{hint}</span>
          )}
        </div>

        {/* 游戏区 */}
        <div className="flex-1 flex flex-col items-center justify-center min-h-0">
          <div ref={gameAreaRef} className="relative w-full flex flex-col items-center gap-4">
            {/* 临时槽位（上方，从右向左开放） */}
            <div className="w-full">
              <div className="text-center text-[10px] text-violet-400/70 mb-1 tracking-wider">临时槽位 · {tempUnlockedCount}/{TEMP_COUNT}</div>
              <div className="flex gap-1 justify-center">
                {[...Array(TEMP_COUNT).keys()].reverse().map((i) => {
                  const cell = tempSlots[i];
                  const unlocked = i < tempUnlockedCount;
                  const isSel = selected?.type === "temp" && selected.index === i;
                  const isTarget = selected !== null && selectedIsMain && targets[COL_COUNT + i];
                  return (
                    <button
                      key={`t-${i}`}
                      ref={(el) => { tempSlotRefs.current[i] = el; }}
                      onClick={() => handleSlotClick({ type: "temp", index: i })}
                      className={`relative flex items-center justify-center rounded-md border-2 transition-all duration-150 ${
                        !unlocked
                          ? "border-slate-600/40 bg-slate-800/40"
                          : isSel
                          ? "border-amber-400/70 bg-amber-400/10"
                          : isTarget
                          ? "border-emerald-400/50 bg-emerald-400/5"
                          : "border-slate-600/30 bg-slate-800/20"
                      }`}
                      style={{ height: TEMP_SLOT_H, width: SLOT_W }}
                    >
                      {!unlocked ? (
                        <Lock size={14} className="text-slate-500" />
                      ) : cell ? (
                        flying && flying.from.type === "temp" && flying.from.index === i ? null : (
                          <Block cell={cell} />
                        )
                      ) : (
                        <span className="text-slate-600 text-[10px] opacity-40">·</span>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* 分隔线 */}
            <div className="w-3/4 h-px bg-gradient-to-r from-transparent via-slate-600/40 to-transparent" />

            {/* 主槽位（下方） */}
            <div className="w-full">
              <div className="text-center text-[10px] text-emerald-400/70 mb-1 tracking-wider">主槽位 · 点击顶部方块移动</div>
              <div className="flex gap-1 justify-center">
                {cols.map((col, c) => {
                  const isSel = selected?.type === "main" && selected.index === c;
                  const isTarget = selected !== null && targets[c];
                  const isFlyingFrom = flying?.from.type === "main" && flying.from.index === c;
                  const displayCol = isFlyingFrom
                    ? col.slice(0, col.length - flying!.cells.length)
                    : col;
                  const topFaceUp = displayCol.length > 0 && displayCol[displayCol.length - 1].faceUp;
                  return (
                    <button
                      key={c}
                      ref={(el) => { columnRefs.current[c] = el; }}
                      onClick={() => handleSlotClick({ type: "main", index: c })}
                      className={`relative flex flex-col justify-end items-center rounded-md border-2 overflow-hidden transition-all duration-150 ${
                        isSel
                          ? "border-amber-400/70 bg-amber-400/10"
                          : isTarget
                          ? "border-emerald-400/50 bg-emerald-400/5"
                          : "border-slate-700/30 bg-slate-800/20"
                      }`}
                      style={{ height: SLOT_H, width: SLOT_W }}
                    >
                      {displayCol.length === 0 && (
                        <span className="text-slate-600 text-sm opacity-40">·</span>
                      )}
                      {[...displayCol].reverse().map((cell, i) => {
                        const inSelectedGroup = isSel && i < selectedGroup.length;
                        const dim = selected !== null && !isSel && !isTarget && cell.faceUp && topFaceUp;
                        return (
                          <div
                            key={i}
                            className={`transition-all duration-150 ${
                              inSelectedGroup ? "ring-2 ring-amber-300 rounded-md scale-105" : ""
                            } ${dim ? "opacity-50" : ""}`}
                            style={{ marginBottom: GAP_PX }}
                          >
                            <Block cell={cell} />
                          </div>
                        );
                      })}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* 飞行方块 overlay */}
            {flying && (
              <div className="absolute left-0 top-0 pointer-events-none" style={{ zIndex: 20 }}>
                <div
                  ref={flyingInnerRef}
                  style={{ transform: `translate3d(${flying.startX}px, ${flying.startY}px, 0)` }}
                >
                  {[...flying.cells].reverse().map((cell, i) => (
                    <div
                      key={i}
                      className="flying-block absolute left-0 top-0"
                      style={{
                        transform: `translate3d(0, ${i * STEP_PX}px, 0)`,
                        filter: "drop-shadow(0 2px 4px rgba(0,0,0,0.35))",
                      }}
                    >
                      <Block cell={cell} />
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* 底部提示 */}
        <p className="text-center text-slate-500 text-[11px] mt-2 shrink-0">
          {selected === null
            ? "点击槽位选中顶部方块，再点目标槽位移动"
            : selectedIsTemp
            ? "临时槽位中的方块可移回主槽位"
            : selectedGroup.length > 1
            ? `已选中 ${selectedGroup.length} 个（整组移动，临时槽仅能放单个）`
            : `已选中 1 个，选择目标槽位`}
        </p>
      </div>

      {/* 规则弹窗 */}
      {showRules && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm px-6" onClick={() => setShowRules(false)}>
          <div
            className="bg-slate-800/95 rounded-2xl border border-slate-600/50 p-5 max-w-sm w-full shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-slate-100 font-bold text-base flex items-center gap-2">
                <span className="text-xl">🌱</span> 玩法说明
              </h2>
              <button onClick={() => setShowRules(false)} className="text-slate-400 hover:text-slate-200 text-lg leading-none">×</button>
            </div>
            <ul className="text-slate-300 text-[13px] space-y-2 leading-relaxed">
              <li>• 共 <span className="text-emerald-300">10 个主槽位</span>，每槽最多 10 格。开局 1 个空槽，其余 9 槽各 9 个方块。</li>
              <li>• 每个主槽位只有<span className="text-amber-300">顶部方块正面朝上</span>，其余背面朝下。</li>
              <li>• 顶部方块被移走后，新暴露的顶部背面方块会<span className="text-emerald-300">翻面</span>。</li>
              <li>• 顶部若有<span className="text-emerald-300">连续同类型</span>的正面方块，可整组一次移走。</li>
              <li>• 只能放到<span className="text-emerald-300">空槽</span>或<span className="text-emerald-300">同类型</span>槽顶，且容量放得下。</li>
              <li>• 凑齐 <span className="text-amber-300">9 个同类型</span>的一槽即归类完成，方块保留占位（不消除）。</li>
              <li>• <span className="text-violet-300">上方 10 个临时槽位</span>，每个只能放 1 个方块，仅能存放单块（整组不可放入）。</li>
              <li>• 初始仅最右侧 1 个临时槽位开放，点击锁定的槽位通过<span className="text-violet-300">学习单词</span>从右向左解锁。</li>
              <li>• 将 9 个槽位全部归类完成即胜利，可触发<span className="text-amber-300">水果机抽奖</span>获得奖励。</li>
            </ul>
            <button
              onClick={() => setShowRules(false)}
              className="w-full mt-4 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white text-sm font-medium transition-all active:scale-95"
            >
              开始整理
            </button>
          </div>
        </div>
      )}

      {/* 解锁弹窗 */}
      <QuizModal
        open={showQuiz}
        onClose={handleQuizClose}
        mode="warehouse"
      />

      {/* 水果机抽奖（胜利时触发） */}
      {showReward && (
        <SlotMachineReward onClose={() => { setShowReward(false); }} />
      )}

      {/* 胜利覆盖 */}
      {won && !showReward && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm px-6" onClick={newGame}>
          <div className="text-center" onClick={(e) => e.stopPropagation()}>
            <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center shadow-2xl shadow-amber-500/40">
              <Trophy className="text-white" size={40} />
            </div>
            <h2 className="text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-amber-300 to-orange-300 mb-2">
              归类完成！
            </h2>
            <p className="text-slate-300 text-sm mb-5">所有方块已归类完毕</p>
            <button
              onClick={newGame}
              className="px-6 py-2.5 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white font-medium transition-all active:scale-95 flex items-center gap-2 mx-auto"
            >
              再来一局
            </button>
          </div>
        </div>
      )}

    </div>
  );
}
