import { useEffect, useRef } from "react";
import { useLocation } from "react-router-dom";
import { supabase } from "@/utils/supabase";
import { getUserInfo } from "@/utils/userInfo";
import {
  useOnlineStore,
  PageLocation,
  OnlinePlayer,
} from "@/store/useOnlineStore";

function pathToLocation(path: string): PageLocation {
  if (path === "/" || path === "") return "home";
  if (path.startsWith("/game")) return "game";
  if (path.startsWith("/farm")) return "farm";
  if (path === "/delivery") return "delivery";
  if (path.startsWith("/delivery/map")) return "map";
  if (path.startsWith("/delivery/loading")) return "loading";
  return "unknown";
}

function locationToText(loc: PageLocation): string {
  const map: Record<PageLocation, string> = {
    home: "首页",
    game: "消消乐",
    farm: "农场",
    delivery: "配送中心",
    map: "配送地图",
    loading: "配送中",
    unknown: "未知",
  };
  return map[loc];
}

export function useOnlinePresence() {
  const location = useLocation();
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);
  const setPlayers = useOnlineStore((s) => s.setPlayers);
  const setConnected = useOnlineStore((s) => s.setConnected);

  useEffect(() => {
    const userInfo = getUserInfo();
    if (!userInfo.uuid) return;

    const channel = supabase.channel("online-players", {
      config: { presence: { key: userInfo.uuid } },
    });

    channelRef.current = channel;

    channel.on("presence", { event: "sync" }, () => {
      const state = channel.presenceState();
      const players: OnlinePlayer[] = [];
      for (const key in state) {
        const entries = state[key] as unknown as Array<{
          uuid: string;
          nickname: string;
          location: PageLocation;
          joinedAt: number;
        }>;
        if (entries.length > 0) {
          const latest = entries[entries.length - 1];
          players.push({
            uuid: latest.uuid,
            nickname: latest.nickname,
            location: latest.location,
            joinedAt: latest.joinedAt,
          });
        }
      }
      setPlayers(players);
      setConnected(true);
    });

    channel.subscribe(async (status) => {
      if (status === "SUBSCRIBED") {
        const loc = pathToLocation(location.pathname);
        await channel.track({
          uuid: userInfo.uuid,
          nickname: userInfo.nickname,
          location: loc,
          joinedAt: Date.now(),
        });
      }
    });

    return () => {
      channel.untrack();
      channel.unsubscribe();
      setConnected(false);
    };
  }, []);

  useEffect(() => {
    const userInfo = getUserInfo();
    if (!userInfo.uuid) return;
    const channel = channelRef.current;
    if (!channel) return;

    const loc = pathToLocation(location.pathname);
    channel.track({
      uuid: userInfo.uuid,
      nickname: userInfo.nickname,
      location: loc,
      joinedAt: Date.now(),
    });
  }, [location.pathname]);
}

export { locationToText, pathToLocation };
